import{z as s,x as d,o as A,c as o,q as t,j as r,D as a,d as B,s as i,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"红队数据的沉淀","description":"","frontmatter":{"title":"红队数据的沉淀","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ade-redteam-data.md","filePath":"llm/ade-redteam-data.md","lastUpdated":1791413859000}'),p={name:"llm/ade-redteam-data.md"};function m(D,E,F,C,h,c){const l=d("Mermaid");return A(),o("div",null,[E[2]||(E[2]=t('<h1 id="红队数据的沉淀" tabindex="-1">红队数据的沉淀 <a class="header-anchor" href="#红队数据的沉淀" aria-label="Permalink to &quot;红队数据的沉淀&quot;">​</a></h1><div class="epigraph"><p>红队给评测的失败要变成给训练的对子；沉淀的对象是边界，不是题面——题面会过时，边界不会。</p><footer>—— 据 Ganguli et al., Red Teaming Language Models with Language Models, 2022 与 Bai et al., 2022 整理</footer></div><p><a href="/llm/ade-prompt-diversity">上一课</a>把提示覆盖钉成意图分类法上的配额问题，但那条分布是正常使用的分布，刻意制造失败的一支不在里面。红队产线本身的工程，<a href="/llm/aeval-redteam-engineering">红队工程</a>已经写成五段漏斗：范围先行、双产线、去重聚类、政策映射、有效失败三条件。本课写漏斗的出口之后：一条有效失败怎么变成训练资产，而不是停在评测的回归集里。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>沉淀缺位有两种失效。其一，评训断路：失败全进了回归集，模型只在评测里「见过」这些边界，训练侧从未学过政策内的正确处理——同一类攻击换皮再来，还是失败，红队每轮都在替模型重新发现同一批洞。其二，粗糙灌库：把攻击原题与有害回答直接倒进训练数据，模型学到的是「这些题面会被拒」的表面关联，换皮即失效；更糟的是只喂危害对不喂对照——模型把「长得像危害的正当内容」一并拒掉，越权拒绝率上去（<a href="/llm/aeval-overrefusal-metric">越权行为的度量</a>的主图就是这么画歪的）。缺口是一段把失败翻译成偏好对、且评训分离的沉淀管线。</p><p><span class="marginnote">「红队」借自安全行业：一队人专门扮演攻击者，想方设法让系统出丑，把漏洞在上线前暴露出来。对语言模型来说，红队就是不断用刁钻话术套模型，看它会不会被骗着说出不该说的话。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>沉淀四步。第一步政策映射已在漏斗里完成，落地时带着政策版本号。第二步构造训练对：rejected 取有害完成或政策违反的输出，chosen 取政策内的正确处理——能安全完成则完成，须拒绝则拒绝并给出替代方向；只教「说不」的对子只覆盖一半边界。第三步配对照对：与攻击题面相似但正当的内容（过度拒绝探针一类的形态）配上正常处理的对子，成对入库——它们是越权拒绝的疫苗。第四步版本绑定与评训分离：私有回归集只进评测门禁，绝不进训练；训练侧用同分布新采的样本，修复后拿回归集复测，背题的假阴性才不会发生。</p>',8)),(A(),r(n,null,{default:a(()=>[i(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAIL%5B%22%E7%BA%A2%E9%98%9F%E5%8F%91%E7%8E%B0%EF%BC%9A%E6%9C%89%E6%95%88%E5%A4%B1%E8%B4%A5%E4%B8%89%E6%9D%A1%E4%BB%B6%22%5D%20--%3E%20MAP%5B%22%E6%94%BF%E7%AD%96%E6%98%A0%E5%B0%84%EF%BC%8C%E5%B8%A6%E7%89%88%E6%9C%AC%E5%8F%B7%22%5D%0A%20%20MAP%20--%3E%20PAIR%5B%22%E8%AE%AD%E7%BB%83%E5%AF%B9%EF%BC%9Arejected%20%E6%9C%89%E5%AE%B3%20%2F%20chosen%20%E6%94%BF%E7%AD%96%E5%86%85%E5%A4%84%E7%90%86%22%5D%0A%20%20MAP%20--%3E%20LOOK%5B%22%E5%AF%B9%E7%85%A7%E5%AF%B9%EF%BC%9A%E7%9B%B8%E4%BC%BC%E6%AD%A3%E5%BD%93%E5%86%85%E5%AE%B9%20%C3%97%20%E6%AD%A3%E5%B8%B8%E5%A4%84%E7%90%86%22%5D%0A%20%20PAIR%20--%3E%20MIX%5B%22%E5%AE%89%E5%85%A8%E6%B1%A0%E5%85%A5%E5%BA%93%22%5D%0A%20%20LOOK%20--%3E%20MIX%0A%20%20FAIL%20--%3E%20REG%5B%22%E7%A7%81%E6%9C%89%E5%9B%9E%E5%BD%92%E9%9B%86%22%5D%0A%20%20REG%20--%3E%7C%22%E5%8F%AA%E8%BF%9B%E8%AF%84%E6%B5%8B%EF%BC%8C%E4%B8%8D%E8%BF%9B%E8%AE%AD%E7%BB%83%22%7C%20RE%5B%22%E5%A4%8D%E6%B5%8B%E9%97%A8%E7%A6%81%22%5D%0A%20%20MIX%20--%3E%20RETRAIN%5B%22%E8%AE%AD%E7%BB%83%22%5D%0A%20%20RETRAIN%20--%3E%20RE%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"为什么必须成对：对齐数据用对比定义边界，只有 rejected 没有 chosen，模型知道什么不要、不知道换成什么——边界外没有正例，行为塌向一律回避。对照对的机制同源：判别边界需要在边界两侧都有样本，只在一侧加压，分界线就向保守侧滑动，这就是越权拒绝的生长机制。评训分离的机制红队课已经给过：回归集若进训练，复测通过测的是记忆不是能力。版本绑定的机制是政策文本即定义：政策一改，「违反」的所指就变了，不带版本号的对子会在下一次改版时集体变成语义不明的资产。",-1)),E[5]||(E[5]=e("p",null,"只喂一半边界与成对喂的后果对比——这就是越权拒绝的生长机制：",-1)),(A(),r(n,null,{default:a(()=>[i(l,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20LR%0A%20%20ONE%5B%22%E5%8F%AA%E5%96%82%E5%8D%B1%E5%AE%B3%E5%AF%B9%EF%BC%9A%E5%8F%AA%E8%A7%81%E3%80%8C%E8%AF%B4%E4%B8%8D%E3%80%8D%22%5D%20--%3E%20S1%5B%22%E8%BE%B9%E7%95%8C%E5%90%91%E4%BF%9D%E5%AE%88%E4%BE%A7%E6%BB%91%E5%8A%A8%22%5D%0A%20%20S1%20--%3E%20BAD%5B%22%E6%AD%A3%E5%BD%93%E5%86%85%E5%AE%B9%E8%A2%AB%E8%AF%AF%E4%BC%A4%EF%BC%9A%E8%B6%8A%E6%9D%83%E6%8B%92%E7%BB%9D%22%5D%0A%20%20BOTH%5B%22%E5%8D%B1%E5%AE%B3%E5%AF%B9%20%2B%20%E5%AF%B9%E7%85%A7%E5%AF%B9%EF%BC%9A%E4%B8%A4%E4%BE%A7%E9%83%BD%E6%9C%89%E6%A0%B7%E6%9C%AC%22%5D%20--%3E%20S2%5B%22%E5%88%86%E7%95%8C%E7%BA%BF%E7%AB%8B%E7%A8%B3%22%5D%0A%20%20S2%20--%3E%20GOOD%5B%22%E8%AF%A5%E6%8B%92%E7%9A%84%E6%8B%92%EF%BC%8C%E8%AF%A5%E7%AD%94%E7%9A%84%E7%AD%94%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<p><span class="marginnote">对照对像疫苗：把「长得像危险但其实没事」的样本提前喂给模型，它以后遇到「怎么杀掉一个进程」「如何彻底注销账号」这类带敏感词的正常问题时，才不会一刀切地拒绝——这些词字面上像攻击，实际是日常运维操作。</span></p><p><span class="marginnote">把攻击配方写进公开数据的双重代价：模型背下配方的应答，攻击者拿到防御面。配方只以聚合口径披露，与评测报告规范的分界一致。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>红队沉淀进安全池的量通常远小于有用池，占比怎么定是配比课的题。沉淀解决「已知边界」的覆盖：自动化攻击器出不了自己分布之外的失败，没发现的边界沉淀不了。裁判被对抗输出骗过时，有效失败的判定本身不可靠，那是评测课的地界。最后，红队数据不是对抗鲁棒性的全部——训练数据补边界，门禁与对抗评测是另两道防线，本课不混着写。</p><p><span class="marginnote">初学者容易以为红队做得多模型就安全了。实际上红队只能发现「已知的洞」：自动化攻击器出不了自己想象之外的失败。所以训练补边界、门禁卡回归、对抗评测再扫一遍，是三道独立的防线，缺哪一道都有缝。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>沉淀把有效失败翻译成训练对：chosen 是政策内正确处理，rejected 是违反样本；只教说不只覆盖一半边界。</li><li>对照对（相似正当内容 × 正常处理）是越权拒绝的疫苗，与危害对成对入库。</li><li>评训分离：回归集只进评测门禁；修复背题的复测通过是假阴性。</li><li>版本绑定：政策文本是「违反」的定义，无版本的对子在改版时集体失义。</li><li>出处：Ganguli et al., 2022；Bai et al., 2022；本课程红队工程与越权度量的口径。</li></ul>',7))])}const _=s(p,[["render",m]]);export{f as __pageData,_ as default};
